    # Format the keyword-only arguments from base classes
    formatted_kw_only = ", ".join([f"{name}: {annotation}" for name, (annotation, default) in prev_kw_only.items()])
    if formatted_kw_only:
        formatted_kw_only += ", "

    # Then we add the keyword only parameters
    if prev_kw_only or kw_only_params:
        params_string += "*, "
    params_string += f"{formatted_kw_only}{', '.join(kw_only_params)}"

    assignments_string = "\n    ".join(assignments) if assignments else "pass"
    return f"def __init__({params_string}) -> None:\n    {assignments_string}"


